AUTHMODAL_PATH = os.path.join(REPO_ROOT, "src", "components", "AuthModal.tsx")

PHONE_SIGNUP_CONTENT = "import { initializeApp, getApps, cert } from \"firebase-admin/app\";\nimport { getFirestore } from \"firebase-admin/firestore\";\nimport { getAuth } from \"firebase-admin/auth\";\nimport crypto from \"crypto\";\n\n// SMS-gateway (OTP) নির্ভরতা বাদ দিয়ে ফোন নম্বর + পাসওয়ার্ড দিয়ে সরাসরি\n// অ্যাকাউন্ট তৈরি। একই ফোন নম্বর দিয়ে আগে OTP-ভিত্তিক অ্যাকাউন্ট খোলা থাকলে\n// (verify-otp.ts একই getUserByPhoneNumber প্যাটার্ন ব্যবহার করে) সেই একই\n// Firebase Auth ইউজারের সাথেই এখন পাসওয়ার্ড যুক্ত হবে -- নতুন করে ডুপ্লিকেট\n// অ্যাকাউন্ট তৈরি হবে না।\n\nif (!getApps().length) {\n  const serviceAccountJson = process.env.FIREBASE_SERVICE_ACCOUNT_KEY;\n  if (serviceAccountJson) {\n    try {\n      const serviceAccount = JSON.parse(serviceAccountJson);\n      initializeApp({ credential: cert(serviceAccount) });\n    } catch (e) {\n      console.error(\"Failed to parse FIREBASE_SERVICE_ACCOUNT_KEY:\", e);\n    }\n  }\n}\n\nfunction normalizeBanglaPhone(raw: string): string | null {\n  const digits = String(raw || \"\").replace(/[^\\d]/g, \"\");\n  let local = digits;\n  if (local.startsWith(\"880\")) local = local.slice(3);\n  if (local.startsWith(\"0\")) local = local.slice(1);\n  if (!/^1[3-9]\\d{8}$/.test(local)) return null;\n  return `+880${local}`;\n}\n\nfunction hashPassword(password: string, salt: string): string {\n  return crypto.scryptSync(password, salt, 64).toString(\"hex\");\n}\n\nexport default async function handler(req: any, res: any) {\n  if (req.method !== \"POST\") {\n    return res.status(405).json({ error: \"Method not allowed\" });\n  }\n\n  try {\n    if (!getApps().length) {\n      return res.status(500).json({ error: \"সার্ভার কনফিগারেশনে সমস্যা।\" });\n    }\n\n    const phone = normalizeBanglaPhone(req.body?.phone);\n    const password = String(req.body?.password || \"\");\n\n    if (!phone) {\n      return res.status(400).json({ error: \"সঠিক মোবাইল নম্বর দিন (যেমন: 01XXXXXXXXX)।\" });\n    }\n    if (password.length < 6) {\n      return res.status(400).json({ error: \"পাসওয়ার্ড কমপক্ষে ৬ ক্যারেক্টার হতে হবে।\" });\n    }\n\n    const db = getFirestore();\n    const authRef = db.collection(\"phone_auth\").doc(phone);\n    const existingSnap = await authRef.get();\n\n    if (existingSnap.exists) {\n      return res.status(409).json({\n        error: \"এই নম্বরে আগে থেকেই অ্যাকাউন্ট আছে। লগইন করুন।\",\n        code: \"ALREADY_REGISTERED\",\n      });\n    }\n\n    const salt = crypto.randomBytes(16).toString(\"hex\");\n    const passwordHash = hashPassword(password, salt);\n\n    await authRef.set({\n      phone,\n      passwordHash,\n      salt,\n      createdAt: Date.now(),\n      failedAttempts: 0,\n      lockUntil: 0,\n    });\n\n    const adminAuth = getAuth();\n    let uid: string;\n    try {\n      const existing = await adminAuth.getUserByPhoneNumber(phone);\n      uid = existing.uid;\n    } catch (e: any) {\n      if (e?.code === \"auth/user-not-found\") {\n        const created = await adminAuth.createUser({ phoneNumber: phone });\n        uid = created.uid;\n      } else {\n        throw e;\n      }\n    }\n\n    const customToken = await adminAuth.createCustomToken(uid);\n    return res.status(200).json({ token: customToken, uid, phone });\n  } catch (err: any) {\n    console.error(\"phone-signup failed:\", err);\n    return res.status(500).json({ error: \"অ্যাকাউন্ট তৈরি করা যায়নি। আবার চেষ্টা করুন।\" });\n  }\n}\n"
PHONE_LOGIN_CONTENT = "import { initializeApp, getApps, cert } from \"firebase-admin/app\";\nimport { getFirestore } from \"firebase-admin/firestore\";\nimport { getAuth } from \"firebase-admin/auth\";\nimport crypto from \"crypto\";\n\nif (!getApps().length) {\n  const serviceAccountJson = process.env.FIREBASE_SERVICE_ACCOUNT_KEY;\n  if (serviceAccountJson) {\n    try {\n      const serviceAccount = JSON.parse(serviceAccountJson);\n      initializeApp({ credential: cert(serviceAccount) });\n    } catch (e) {\n      console.error(\"Failed to parse FIREBASE_SERVICE_ACCOUNT_KEY:\", e);\n    }\n  }\n}\n\nconst MAX_FAILED_ATTEMPTS = 5;\nconst LOCK_DURATION_MS = 15 * 60 * 1000; // 15 minutes\n\nfunction normalizeBanglaPhone(raw: string): string | null {\n  const digits = String(raw || \"\").replace(/[^\\d]/g, \"\");\n  let local = digits;\n  if (local.startsWith(\"880\")) local = local.slice(3);\n  if (local.startsWith(\"0\")) local = local.slice(1);\n  if (!/^1[3-9]\\d{8}$/.test(local)) return null;\n  return `+880${local}`;\n}\n\nfunction hashPassword(password: string, salt: string): string {\n  return crypto.scryptSync(password, salt, 64).toString(\"hex\");\n}\n\nexport default async function handler(req: any, res: any) {\n  if (req.method !== \"POST\") {\n    return res.status(405).json({ error: \"Method not allowed\" });\n  }\n\n  try {\n    if (!getApps().length) {\n      return res.status(500).json({ error: \"সার্ভার কনফিগারেশনে সমস্যা।\" });\n    }\n\n    const phone = normalizeBanglaPhone(req.body?.phone);\n    const password = String(req.body?.password || \"\");\n\n    if (!phone || !password) {\n      return res.status(400).json({ error: \"মোবাইল নম্বর ও পাসওয়ার্ড দিন।\" });\n    }\n\n    const db = getFirestore();\n    const authRef = db.collection(\"phone_auth\").doc(phone);\n    const snap = await authRef.get();\n\n    if (!snap.exists) {\n      return res.status(404).json({\n        error: \"এই নম্বরে কোনো অ্যাকাউন্ট পাওয়া যায়নি। নতুন অ্যাকাউন্ট তৈরি করুন।\",\n        code: \"NOT_REGISTERED\",\n      });\n    }\n\n    const data = snap.data() as any;\n    const now = Date.now();\n\n    if (data.lockUntil && now < data.lockUntil) {\n      const waitMin = Math.ceil((data.lockUntil - now) / 60000);\n      return res.status(429).json({\n        error: `অনেকবার ভুল পাসওয়ার্ড দেওয়া হয়েছে। ${waitMin} মিনিট পর আবার চেষ্টা করুন।`,\n      });\n    }\n\n    const computedHash = hashPassword(password, data.salt);\n    const stored = Buffer.from(data.passwordHash, \"hex\");\n    const computed = Buffer.from(computedHash, \"hex\");\n    const matches = stored.length === computed.length && crypto.timingSafeEqual(stored, computed);\n\n    if (!matches) {\n      const failedAttempts = (data.failedAttempts || 0) + 1;\n      const update: any = { failedAttempts };\n      if (failedAttempts >= MAX_FAILED_ATTEMPTS) {\n        update.lockUntil = now + LOCK_DURATION_MS;\n        update.failedAttempts = 0;\n      }\n      await authRef.update(update);\n      return res.status(400).json({ error: \"ভুল পাসওয়ার্ড। আবার চেষ্টা করুন।\" });\n    }\n\n    if (data.failedAttempts || data.lockUntil) {\n      await authRef.update({ failedAttempts: 0, lockUntil: 0 });\n    }\n\n    const adminAuth = getAuth();\n    let uid: string;\n    try {\n      const existing = await adminAuth.getUserByPhoneNumber(phone);\n      uid = existing.uid;\n    } catch (e: any) {\n      if (e?.code === \"auth/user-not-found\") {\n        const created = await adminAuth.createUser({ phoneNumber: phone });\n        uid = created.uid;\n      } else {\n        throw e;\n      }\n    }\n\n    const customToken = await adminAuth.createCustomToken(uid);\n    return res.status(200).json({ token: customToken, uid, phone });\n  } catch (err: any) {\n    console.error(\"phone-login failed:\", err);\n    return res.status(500).json({ error: \"লগইন ব্যর্থ হয়েছে। আবার চেষ্টা করুন।\" });\n  }\n}\n"

