AUTHMODAL_OLD = "import React, { useState, useRef } from \"react\";\nimport { auth, db, googleProvider, facebookProvider } from \"../firebase\";\nimport {\n  signInWithPopup,\n  signInWithRedirect,\n  signInWithCustomToken,\n  getRedirectResult,\n  signOut,\n  User as FirebaseUser,\n} from \"firebase/auth\";\nimport { doc, getDoc, setDoc } from \"firebase/firestore\";\nimport { X, MapPin, Loader2, Sparkles, Camera, Phone, ArrowLeft } from \"lucide-react\";\nimport { CITIES } from \"../translations\";\nimport { SupportedLanguage } from \"../types\";\nimport { sanitizeText, validateBanglaPhone } from \"../utils/sanitizer\";\nimport { uploadToCloudinary } from \"../utils/cloudinary\";\nimport { trackEvent } from \"../utils/trackEvent\";\n\ninterface AuthModalProps {\n  isOpen: boolean;\n  onClose: () => void;\n  language: SupportedLanguage;\n  onAuthSuccess: (user: any) => void;\n}\n\nconst PRESET_AVATARS = [\n  \"https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=150&auto=format&fit=crop&q=80\"\n];\n\nconst compressImageToBlob = async (file: File, maxWidth = 512, maxHeight = 512): Promise<Blob> => {\n  const img = await new Promise<HTMLImageElement>((resolve, reject) => {\n    const objectUrl = URL.createObjectURL(file);\n    const image = new Image();\n    image.onload = () => {\n      URL.revokeObjectURL(objectUrl);\n      resolve(image);\n    };\n    image.onerror = () => {\n      URL.revokeObjectURL(objectUrl);\n      reject(new Error(\"Failed to load image for compression\"));\n    };\n    image.src = objectUrl;\n  });\n\n  let { width, height } = img;\n  if (width > height) {\n    if (width > maxWidth) {\n      height = Math.round((height * maxWidth) / width);\n      width = maxWidth;\n    }\n  } else if (height > maxHeight) {\n    width = Math.round((width * maxHeight) / height);\n    height = maxHeight;\n  }\n\n  const canvas = document.createElement(\"canvas\");\n  canvas.width = width;\n  canvas.height = height;\n  const ctx = canvas.getContext(\"2d\");\n  if (!ctx) throw new Error(\"Canvas context is null\");\n  ctx.drawImage(img, 0, 0, width, height);\n\n  return await new Promise<Blob>((resolve, reject) => {\n    canvas.toBlob((b) => {\n      if (!b) reject(new Error(\"Failed to convert canvas to Blob\"));\n      else resolve(b);\n    }, \"image/jpeg\", 0.8);\n  });\n};\n\nconst GoogleIcon = () => (\n  <svg className=\"w-5 h-5\" viewBox=\"0 0 48 48\" aria-hidden=\"true\">\n    <path fill=\"#FFC107\" d=\"M43.611 20.083H42V20H24v8h11.303c-1.649 4.657-6.08 8-11.303 8-6.627 0-12-5.373-12-12s5.373-12 12-12c3.059 0 5.842 1.154 7.961 3.039l5.657-5.657C34.046 6.053 29.268 4 24 4 12.955 4 4 12.955 4 24s8.955 20 20 20 20-8.955 20-20c0-1.341-.138-2.65-.389-3.917z\"/>\n    <path fill=\"#FF3D00\" d=\"M6.306 14.691l6.571 4.819C14.655 15.108 18.961 12 24 12c3.059 0 5.842 1.154 7.961 3.039l5.657-5.657C34.046 6.053 29.268 4 24 4 16.318 4 9.656 8.337 6.306 14.691z\"/>\n    <path fill=\"#4CAF50\" d=\"M24 44c5.166 0 9.86-1.977 13.409-5.192l-6.19-5.238C29.211 35.091 26.715 36 24 36c-5.202 0-9.619-3.317-11.283-7.946l-6.522 5.025C9.505 39.556 16.227 44 24 44z\"/>\n    <path fill=\"#1976D2\" d=\"M43.611 20.083H42V20H24v8h11.303a12.04 12.04 0 0 1-4.087 5.571l.003-.002 6.19 5.238C36.971 39.205 44 34 44 24c0-1.341-.138-2.65-.389-3.917z\"/>\n  </svg>\n);\n\nconst FacebookIcon = () => (\n  <svg className=\"w-5 h-5\" viewBox=\"0 0 24 24\" aria-hidden=\"true\">\n    <path fill=\"#1877F2\" d=\"M24 12.073c0-6.627-5.373-12-12-12s-12 5.373-12 12c0 5.99 4.388 10.954 10.125 11.854v-8.385H7.078v-3.47h3.047V9.43c0-3.007 1.792-4.669 4.533-4.669 1.312 0 2.686.235 2.686.235v2.953H15.83c-1.491 0-1.956.925-1.956 1.874v2.25h3.328l-.532 3.47h-2.796v8.385C19.612 23.027 24 18.062 24 12.073z\"/>\n  </svg>\n);\n\nexport function AuthModal({ isOpen, onClose, language, onAuthSuccess }: AuthModalProps) {\n  const [error, setError] = useState(\"\");\n  const [loading, setLoading] = useState(false);\n\n  const [step, setStep] = useState<\"start\" | \"phone\" | \"otp\" | \"profile\">(\"start\");\n  const [googleUser, setGoogleUser] = useState<FirebaseUser | null>(null);\n  const [otpPhone, setOtpPhone] = useState(\"\");\n  const [otpCode, setOtpCode] = useState(\"\");\n  const [displayName, setDisplayName] = useState(\"\");\n  const [phoneNumber, setPhoneNumber] = useState(\"\");\n  const [city, setCity] = useState(CITIES[0]);\n  const [profilePhotoFile, setProfilePhotoFile] = useState<File | null>(null);\n  const [profilePhotoPreview, setProfilePhotoPreview] = useState<string | null>(null);\n  const [uploadingPhoto, setUploadingPhoto] = useState(false);\n  const fileInputRef = useRef<HTMLInputElement>(null);\n\n  const handlePostGoogleAuth = async (fbUser: FirebaseUser) => {\n    const userDocRef = doc(db, \"users\", fbUser.uid);\n    const userSnap = await getDoc(userDocRef);\n\n    if (userSnap.exists()) {\n      const existingData = userSnap.data() as any;\n      const sessionUser = {\n        uid: fbUser.uid,\n        displayName: existingData.displayName,\n        email: existingData.email || fbUser.email,\n        phoneNumber: existingData.phoneNumber,\n        city: existingData.city,\n        profilePicture: existingData.profilePicture || fbUser.photoURL || PRESET_AVATARS[0],\n        simulatedCredits: existingData.simulatedCredits ?? 5000,\n        referralCode: existingData.referralCode,\n      };\n      localStorage.setItem(\"gari_bazar_session_user\", JSON.stringify(sessionUser));\n      trackEvent(\"login\", fbUser.uid, sessionUser.email || sessionUser.phoneNumber);\n      onAuthSuccess(sessionUser);\n      onClose();\n      return;\n    }\n\n    setGoogleUser(fbUser);\n    setDisplayName(fbUser.displayName || \"\");\n    setProfilePhotoPreview(fbUser.photoURL || null);\n    setStep(\"profile\");\n  };\n\n  React.useEffect(() => {\n    (async () => {\n      try {\n        const result = await getRedirectResult(auth);\n        if (result?.user) {\n          await handlePostGoogleAuth(result.user);\n        }\n      } catch (err) {\n        console.error(\"Redirect sign-in failed:\", err);\n      }\n    })();\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, []);\n\n  React.useEffect(() => {\n    if (!isOpen) {\n      setStep(\"start\");\n      setError(\"\");\n    }\n  }, [isOpen]);\n\n  if (!isOpen) return null;\n\n  const handlePhotoSelect = (e: React.ChangeEvent<HTMLInputElement>) => {\n    const file = e.target.files?.[0];\n    if (!file) return;\n\n    if (!file.type.startsWith(\"image/\")) {\n      setError(language === \"bn\" ? \"শুধু ছবি ফাইল দিতে পারবেন\" : \"Only image files are allowed\");\n      return;\n    }\n    if (file.size > 5 * 1024 * 1024) {\n      setError(language === \"bn\" ? \"ছবির সাইজ ৫MB এর কম হতে হবে\" : \"Photo must be under 5MB\");\n      return;\n    }\n\n    setError(\"\");\n    setProfilePhotoFile(file);\n    if (profilePhotoPreview) URL.revokeObjectURL(profilePhotoPreview);\n    setProfilePhotoPreview(URL.createObjectURL(file));\n  };\n\n  const handleGoogleSignIn = async () => {\n    setError(\"\");\n    setLoading(true);\n    try {\n      // Popup first on every device. signInWithRedirect depends on Firebase's\n      // authDomain (garibazar-bd.firebaseapp.com) sharing storage/cookies with\n      // this app's real hosting domain to hand back the result — Chrome's\n      // third-party storage partitioning breaks that bridge, which is why\n      // redirect sign-in was silently failing to persist. Popup avoids that\n      // entirely since it completes and resolves in the same tab session.\n      const result = await signInWithPopup(auth, googleProvider);\n      await handlePostGoogleAuth(result.user);\n    } catch (err: any) {\n      const code = err?.code || \"\";\n      if (code === \"auth/popup-closed-by-user\" || code === \"auth/cancelled-popup-request\") {\n        // ইউজার নিজেই popup বন্ধ করেছে\n      } else if (\n        code === \"auth/popup-blocked\" ||\n        code === \"auth/operation-not-supported-in-this-environment\"\n      ) {\n        try {\n          await signInWithRedirect(auth, googleProvider);\n          return;\n        } catch (redirectErr) {\n          console.error(redirectErr);\n          setError(language === \"bn\" ? \"Google সাইন-ইন করা যায়নি।\" : \"Could not sign in with Google.\");\n        }\n      } else {\n        console.error(err);\n        setError(language === \"bn\" ? \"Google সাইন-ইন ব্যর্থ হয়েছে। আবার চেষ্টা করুন।\" : \"Google sign-in failed. Please try again.\");\n      }\n    } finally {\n      setLoading(false);\n    }\n  };\n\n  const handleFacebookSignIn = async () => {\n    setError(\"\");\n    setLoading(true);\n    try {\n      const result = await signInWithPopup(auth, facebookProvider);\n      await handlePostGoogleAuth(result.user);\n    } catch (err: any) {\n      const code = err?.code || \"\";\n      if (code === \"auth/popup-closed-by-user\" || code === \"auth/cancelled-popup-request\") {\n        // ইউজার নিজেই popup বন্ধ করেছে\n      } else if (code === \"auth/account-exists-with-different-credential\") {\n        setError(\n          language === \"bn\"\n            ? \"এই ইমেইল দিয়ে আগে অন্য পদ্ধতিতে (যেমন Google) অ্যাকাউন্ট খোলা আছে। সেটা দিয়ে সাইন-ইন করুন।\"\n            : \"An account already exists with this email using a different sign-in method. Please use that instead.\"\n        );\n      } else if (\n        code === \"auth/popup-blocked\" ||\n        code === \"auth/operation-not-supported-in-this-environment\"\n      ) {\n        try {\n          await signInWithRedirect(auth, facebookProvider);\n          return;\n        } catch (redirectErr) {\n          console.error(redirectErr);\n          setError(language === \"bn\" ? \"Facebook সাইন-ইন করা যায়নি।\" : \"Could not sign in with Facebook.\");\n        }\n      } else {\n        console.error(err);\n        setError(language === \"bn\" ? \"Facebook সাইন-ইন ব্যর্থ হয়েছে। আবার চেষ্টা করুন।\" : \"Facebook sign-in failed. Please try again.\");\n      }\n    } finally {\n      setLoading(false);\n    }\n  };\n\n  const handleSendOtp = async (e: React.FormEvent) => {\n    e.preventDefault();\n    setError(\"\");\n    const cleanPhone = otpPhone.replace(/\\D/g, \"\");\n    if (!validateBanglaPhone(cleanPhone)) {\n      setError(language === \"bn\" ? \"সঠিক ১১ ডিজিটের মোবাইল নম্বর দিন\" : \"Enter a valid 11-digit phone number\");\n      return;\n    }\n    setLoading(true);\n    try {\n      const resp = await fetch(\"/api/auth/send-otp\", {\n        method: \"POST\",\n        headers: { \"Content-Type\": \"application/json\" },\n        body: JSON.stringify({ phone: cleanPhone }),\n      });\n      const data = await resp.json();\n      if (!resp.ok) {\n        setError(data.error || (language === \"bn\" ? \"OTP পাঠানো যায়নি।\" : \"Could not send OTP.\"));\n        return;\n      }\n      setOtpCode(\"\");\n      setStep(\"otp\");\n    } catch (err) {\n      console.error(err);\n      setError(`DEBUG: ${err?.message || err?.name || String(err)}`);\n    } finally {\n      setLoading(false);\n    }\n  };\n\n  const handleVerifyOtp = async (e: React.FormEvent) => {\n    e.preventDefault();\n    setError(\"\");\n    if (!/^\\d{6}$/.test(otpCode)) {\n      setError(language === \"bn\" ? \"৬-সংখ্যার কোড দিন\" : \"Enter the 6-digit code\");\n      return;\n    }\n    setLoading(true);\n    try {\n      const resp = await fetch(\"/api/auth/verify-otp\", {\n        method: \"POST\",\n        headers: { \"Content-Type\": \"application/json\" },\n        body: JSON.stringify({ phone: otpPhone.replace(/\\D/g, \"\"), code: otpCode }),\n      });\n      const data = await resp.json();\n      if (!resp.ok) {\n        setError(data.error || (language === \"bn\" ? \"ভেরিফিকেশন ব্যর্থ হয়েছে।\" : \"Verification failed.\"));\n        return;\n      }\n      const result = await signInWithCustomToken(auth, data.token);\n      await handlePostGoogleAuth(result.user);\n    } catch (err) {\n      console.error(err);\n      setError(language === \"bn\" ? \"সাইন-ইন ব্যর্থ হয়েছে। আবার চেষ্টা করুন।\" : \"Sign-in failed. Please try again.\");\n    } finally {\n      setLoading(false);\n    }\n  };\n\n  const handleCancelProfileStep = async () => {\n    try { await signOut(auth); } catch { /* ignore */ }\n    setGoogleUser(null);\n    setStep(\"start\");\n    setError(\"\");\n  };\n\n  const handleCompleteProfile = async (e: React.FormEvent) => {\n    e.preventDefault();\n    setError(\"\");\n    if (!googleUser) return;\n\n    const cleanPhone = phoneNumber.replace(/\\D/g, \"\");\n    if (!validateBanglaPhone(cleanPhone)) {\n      setError(language === \"bn\" ? \"সঠিক ১১ ডিজিটের মোবাইল নম্বর দিন\" : \"Enter a valid 11-digit phone number\");\n      return;\n    }\n\n    setLoading(true);\n    try {\n      const sanitizedDisplayName = sanitizeText(displayName || googleUser.displayName || \"Gari Bazar Seller\", 50);\n      const myReferralCode = `GB-${cleanPhone.slice(-4)}`;\n\n      let uploadedPhotoUrl = googleUser.photoURL || PRESET_AVATARS[0];\n      if (profilePhotoFile) {\n        setUploadingPhoto(true);\n        try {\n          const compressedBlob = await compressImageToBlob(profilePhotoFile);\n          const uploadPromise = uploadToCloudinary(compressedBlob);\n          const timeoutPromise = new Promise<never>((_, reject) =>\n            setTimeout(() => reject(new Error(\"upload/timeout\")), 60000)\n          );\n          uploadedPhotoUrl = await Promise.race([uploadPromise, timeoutPromise]);\n        } catch (photoErr: any) {\n          console.error(\"Profile photo upload failed:\", photoErr);\n          setUploadingPhoto(false);\n          setLoading(false);\n          setError(\n            photoErr?.message === \"upload/timeout\"\n              ? (language === \"bn\" ? \"ছবি আপলোড আটকে গেছে (Timeout)! আবার চেষ্টা করুন।\" : \"Photo upload timed out. Please try again.\")\n              : (language === \"bn\" ? \"ছবি আপলোড ব্যর্থ হয়েছে। আবার চেষ্টা করুন অথবা ছবি ছাড়াই এগিয়ে যান।\" : \"Photo upload failed. Try again or continue without a photo.\")\n          );\n          return;\n        }\n        setUploadingPhoto(false);\n      }\n\n      const savedData = {\n        uid: googleUser.uid,\n        displayName: sanitizedDisplayName,\n        email: googleUser.email,\n        phoneNumber: cleanPhone,\n        city: sanitizeText(city, 50),\n        profilePicture: uploadedPhotoUrl,\n        createdAt: new Date().toISOString(),\n        simulatedCredits: 5000,\n        referralCode: myReferralCode,\n      };\n\n      await setDoc(doc(db, \"users\", googleUser.uid), savedData);\n      localStorage.setItem(\"gari_bazar_session_user\", JSON.stringify(savedData));\n      trackEvent(\"signup\", googleUser.uid, savedData.email || savedData.phoneNumber);\n      onAuthSuccess(savedData);\n      onClose();\n    } catch (err) {\n      console.error(err);\n      setError(language === \"bn\" ? \"কিছু একটা সমস্যা হয়েছে।\" : \"Something went wrong.\");\n    } finally {\n      setLoading(false);\n    }\n  };\n\n  return (\n    <div className=\"fixed inset-0 bg-slate-900/60 backdrop-blur-xs flex items-center justify-center p-4 z-50\">\n      <div className=\"bg-white dark:bg-slate-900 rounded-2xl max-w-md w-full shadow-2xl p-6 relative\">\n        <button onClick={onClose} className=\"absolute top-4 right-4 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200\">\n          <X className=\"w-5 h-5\" />\n        </button>\n\n        <div className=\"text-center mb-6\">\n          <h2 className=\"text-xl font-black text-slate-900 dark:text-white\">\n            {step === \"profile\"\n              ? (language === \"bn\" ? \"প্রোফাইল সম্পূর্ণ করুন\" : \"Complete Your Profile\")\n              : (language === \"bn\" ? \"স্বাগতম\" : \"Welcome\")}\n          </h2>\n        </div>\n\n        {error && <div className=\"p-3 bg-red-500/10 text-red-600 rounded-lg text-xs mb-3 text-center\">{error}</div>}\n\n        {step === \"start\" ? (\n          <div className=\"space-y-4\">\n            <p className=\"text-sm text-slate-500 dark:text-slate-400 text-center\">\n              {language === \"bn\"\n                ? \"গাড়ি বাজারে বিক্রি করতে বা কেনার জন্য সাইন-ইন করুন।\"\n                : \"Sign in to buy or sell on Gari Bazar.\"}\n            </p>\n            <button\n              type=\"button\"\n              onClick={handleGoogleSignIn}\n              disabled={loading}\n              className=\"w-full py-2.5 bg-white hover:bg-slate-50 disabled:opacity-60 text-slate-700 font-bold rounded-lg text-sm flex items-center justify-center gap-2 border border-slate-300 dark:border-slate-600 dark:bg-slate-800 dark:text-white dark:hover:bg-slate-700\"\n            >\n              {loading ? <Loader2 className=\"w-4 h-4 animate-spin\" /> : <GoogleIcon />}\n              {language === \"bn\" ? \"Google দিয়ে চালিয়ে যান\" : \"Continue with Google\"}\n            </button>\n            <button\n              type=\"button\"\n              onClick={() => { setError(\"\"); setStep(\"phone\"); }}\n              disabled={loading}\n              className=\"w-full py-2.5 bg-emerald-600 hover:bg-emerald-700 disabled:opacity-60 text-white font-bold rounded-lg text-sm flex items-center justify-center gap-2\"\n            >\n              <Phone className=\"w-4 h-4\" />\n              {language === \"bn\" ? \"মোবাইল নম্বর দিয়ে চালিয়ে যান\" : \"Continue with Phone\"}\n            </button>\n          </div>\n        ) : step === \"phone\" ? (\n          <form onSubmit={handleSendOtp} className=\"space-y-4\">\n            <p className=\"text-xs text-slate-500 text-center\">\n              {language === \"bn\"\n                ? \"আপনার মোবাইল নম্বর দিন, আমরা একটা যাচাইকরণ কোড (OTP) পাঠাবো।\"\n                : \"Enter your mobile number and we'll send a verification code (OTP).\"}\n            </p>\n            <div>\n              <label className=\"text-[10px] font-bold block mb-1 text-slate-500\">{language === \"bn\" ? \"মোবাইল নম্বর *\" : \"Mobile Number *\"}</label>\n              <input\n                type=\"tel\"\n                required\n                autoFocus\n                value={otpPhone}\n                onChange={(e) => setOtpPhone(e.target.value)}\n                className=\"w-full px-3 py-2 text-sm border rounded-lg dark:bg-slate-800 dark:border-slate-700 dark:text-white\"\n                placeholder=\"01XXXXXXXXX\"\n              />\n            </div>\n            <button type=\"submit\" disabled={loading} className=\"w-full py-2.5 bg-emerald-600 hover:bg-emerald-700 disabled:opacity-60 text-white font-bold rounded-lg text-sm flex items-center justify-center gap-2\">\n              {loading ? <Loader2 className=\"w-4 h-4 animate-spin\" /> : <Phone className=\"w-4 h-4\" />}\n              {language === \"bn\" ? \"কোড পাঠান\" : \"Send Code\"}\n            </button>\n            <button type=\"button\" onClick={() => { setError(\"\"); setStep(\"start\"); }} className=\"w-full flex items-center justify-center gap-1 text-xs text-slate-500 hover:underline\">\n              <ArrowLeft className=\"w-3 h-3\" />\n              {language === \"bn\" ? \"পেছনে যান\" : \"Back\"}\n            </button>\n          </form>\n        ) : step === \"otp\" ? (\n          <form onSubmit={handleVerifyOtp} className=\"space-y-4\">\n            <p className=\"text-xs text-slate-500 text-center\">\n              {language === \"bn\"\n                ? `${otpPhone} নম্বরে পাঠানো ৬-সংখ্যার কোডটি দিন।`\n                : `Enter the 6-digit code sent to ${otpPhone}.`}\n            </p>\n            <div>\n              <label className=\"text-[10px] font-bold block mb-1 text-slate-500\">{language === \"bn\" ? \"OTP কোড *\" : \"OTP Code *\"}</label>\n              <input\n                type=\"text\"\n                inputMode=\"numeric\"\n                required\n                autoFocus\n                maxLength={6}\n                value={otpCode}\n                onChange={(e) => setOtpCode(e.target.value.replace(/\\D/g, \"\").slice(0, 6))}\n                className=\"w-full px-3 py-2 text-center text-lg tracking-[0.5em] border rounded-lg dark:bg-slate-800 dark:border-slate-700 dark:text-white\"\n                placeholder=\"······\"\n              />\n            </div>\n            <button type=\"submit\" disabled={loading} className=\"w-full py-2.5 bg-emerald-600 hover:bg-emerald-700 disabled:opacity-60 text-white font-bold rounded-lg text-sm flex items-center justify-center gap-2\">\n              {loading ? <Loader2 className=\"w-4 h-4 animate-spin\" /> : <Sparkles className=\"w-4 h-4\" />}\n              {language === \"bn\" ? \"যাচাই করুন\" : \"Verify\"}\n            </button>\n            <div className=\"flex items-center justify-between text-xs\">\n              <button type=\"button\" onClick={() => { setError(\"\"); setStep(\"phone\"); }} className=\"flex items-center gap-1 text-slate-500 hover:underline\">\n                <ArrowLeft className=\"w-3 h-3\" />\n                {language === \"bn\" ? \"নম্বর বদলান\" : \"Change number\"}\n              </button>\n              <button type=\"button\" onClick={handleSendOtp as any} disabled={loading} className=\"text-emerald-600 font-bold hover:underline disabled:opacity-60\">\n                {language === \"bn\" ? \"আবার কোড পাঠান\" : \"Resend code\"}\n              </button>\n            </div>\n          </form>\n        ) : (\n          <form onSubmit={handleCompleteProfile} className=\"space-y-4\">\n            <p className=\"text-xs text-slate-500 text-center\">\n              {language === \"bn\"\n                ? \"শেষ ধাপ! ক্রেতারা যেন আপনার সাথে যোগাযোগ করতে পারে, তাই একটা মোবাইল নম্বর ও জেলা দিন।\"\n                : \"Almost done! Add a phone number and district so buyers can contact you.\"}\n            </p>\n\n            <div className=\"flex justify-center mb-2\">\n              <button\n                type=\"button\"\n                onClick={() => fileInputRef.current?.click()}\n                className=\"relative w-20 h-20 rounded-full overflow-hidden border-2 border-dashed border-slate-300 dark:border-slate-600 flex items-center justify-center bg-slate-50 dark:bg-slate-800\"\n              >\n                {profilePhotoPreview ? (\n                  <>\n                    <img src={profilePhotoPreview} alt=\"preview\" className=\"w-full h-full object-cover\" />\n                    <span className=\"absolute bottom-0 inset-x-0 bg-slate-900/60 text-white flex items-center justify-center py-1\">\n                      <Camera className=\"w-3.5 h-3.5\" />\n                    </span>\n                  </>\n                ) : (\n                  <>\n                    <Camera className=\"w-6 h-6 text-slate-400\" />\n                    <div className=\"absolute bottom-0 inset-x-0 bg-black/50 text-white text-[9px] font-bold text-center py-0.5\">\n                      {language === \"bn\" ? \"ছবি দিন\" : \"Add Photo\"}\n                    </div>\n                  </>\n                )}\n              </button>\n              <input type=\"file\" ref={fileInputRef} onChange={handlePhotoSelect} accept=\"image/*\" className=\"hidden\" />\n            </div>\n\n            <div>\n              <label className=\"text-[10px] font-bold block mb-1 text-slate-500\">{language === \"bn\" ? \"আপনার নাম *\" : \"Name *\"}</label>\n              <div className=\"relative\">\n                <input type=\"text\" required value={displayName} onChange={(e) => setDisplayName(e.target.value)} className=\"w-full px-3 py-2 text-sm border rounded-lg dark:bg-slate-800 dark:border-slate-700 dark:text-white\" placeholder=\"Rayhan\" />\n              </div>\n            </div>\n\n            <div>\n              <label className=\"text-[10px] font-bold block mb-1 text-slate-500\">{language === \"bn\" ? \"মোবাইল নম্বর *\" : \"Mobile Number *\"}</label>\n              <div className=\"relative\">\n                <input type=\"tel\" required value={phoneNumber} onChange={(e) => setPhoneNumber(e.target.value)} className=\"w-full px-3 py-2 text-sm border rounded-lg dark:bg-slate-800 dark:border-slate-700 dark:text-white\" placeholder=\"01993878271\" />\n              </div>\n              <p className=\"text-[10px] text-slate-400 mt-1\">\n                {language === \"bn\" ? \"এই নম্বরে OTP পাঠানো হবে না — শুধু যোগাযোগের জন্য দেখানো হবে।\" : \"No OTP is sent here — it's shown to buyers as your contact number.\"}\n              </p>\n            </div>\n\n            <div>\n              <label className=\"text-[10px] font-bold block mb-1 text-slate-500\">{language === \"bn\" ? \"জেলা *\" : \"District *\"}</label>\n              <div className=\"relative\">\n                <MapPin className=\"w-4 h-4 text-slate-400 absolute left-3 top-3\" />\n                <select value={city} onChange={(e) => setCity(e.target.value)} className=\"w-full pl-9 pr-3 py-2 text-sm border rounded-lg dark:bg-slate-800 dark:border-slate-700 dark:text-white appearance-none\">\n                  {CITIES.map((c) => <option key={c} value={c}>{c}</option>)}\n                </select>\n              </div>\n            </div>\n\n            <button type=\"submit\" disabled={loading} className=\"w-full py-2.5 bg-amber-500 hover:bg-amber-600 disabled:bg-amber-300 text-white font-bold rounded-lg text-sm flex items-center justify-center gap-2\">\n              {loading ? <Loader2 className=\"w-4 h-4 animate-spin\" /> : <Sparkles className=\"w-4 h-4\" />}\n              {uploadingPhoto\n                ? (language === \"bn\" ? \"ছবি আপলোড হচ্ছে...\" : \"Uploading photo...\")\n                : (language === \"bn\" ? \"প্রোফাইল তৈরি করুন\" : \"Create Profile\")}\n            </button>\n\n            <button type=\"button\" onClick={handleCancelProfileStep} className=\"w-full text-center text-xs text-slate-500 hover:underline\">\n              {language === \"bn\" ? \"← বাতিল করুন\" : \"← Cancel\"}\n            </button>\n          </form>\n        )}\n      </div>\n    </div>\n  );\n      }\n"
AUTHMODAL_NEW = "import React, { useState, useRef } from \"react\";\nimport { auth, db, googleProvider, facebookProvider } from \"../firebase\";\nimport {\n  signInWithPopup,\n  signInWithRedirect,\n  signInWithCustomToken,\n  getRedirectResult,\n  signOut,\n  User as FirebaseUser,\n} from \"firebase/auth\";\nimport { doc, getDoc, setDoc } from \"firebase/firestore\";\nimport { X, MapPin, Loader2, Sparkles, Camera, Phone, ArrowLeft } from \"lucide-react\";\nimport { CITIES } from \"../translations\";\nimport { SupportedLanguage } from \"../types\";\nimport { sanitizeText, validateBanglaPhone } from \"../utils/sanitizer\";\nimport { uploadToCloudinary } from \"../utils/cloudinary\";\nimport { trackEvent } from \"../utils/trackEvent\";\n\ninterface AuthModalProps {\n  isOpen: boolean;\n  onClose: () => void;\n  language: SupportedLanguage;\n  onAuthSuccess: (user: any) => void;\n}\n\nconst PRESET_AVATARS = [\n  \"https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=150&auto=format&fit=crop&q=80\"\n];\n\nconst compressImageToBlob = async (file: File, maxWidth = 512, maxHeight = 512): Promise<Blob> => {\n  const img = await new Promise<HTMLImageElement>((resolve, reject) => {\n    const objectUrl = URL.createObjectURL(file);\n    const image = new Image();\n    image.onload = () => {\n      URL.revokeObjectURL(objectUrl);\n      resolve(image);\n    };\n    image.onerror = () => {\n      URL.revokeObjectURL(objectUrl);\n      reject(new Error(\"Failed to load image for compression\"));\n    };\n    image.src = objectUrl;\n  });\n\n  let { width, height } = img;\n  if (width > height) {\n    if (width > maxWidth) {\n      height = Math.round((height * maxWidth) / width);\n      width = maxWidth;\n    }\n  } else if (height > maxHeight) {\n    width = Math.round((width * maxHeight) / height);\n    height = maxHeight;\n  }\n\n  const canvas = document.createElement(\"canvas\");\n  canvas.width = width;\n  canvas.height = height;\n  const ctx = canvas.getContext(\"2d\");\n  if (!ctx) throw new Error(\"Canvas context is null\");\n  ctx.drawImage(img, 0, 0, width, height);\n\n  return await new Promise<Blob>((resolve, reject) => {\n    canvas.toBlob((b) => {\n      if (!b) reject(new Error(\"Failed to convert canvas to Blob\"));\n      else resolve(b);\n    }, \"image/jpeg\", 0.8);\n  });\n};\n\nconst GoogleIcon = () => (\n  <svg className=\"w-5 h-5\" viewBox=\"0 0 48 48\" aria-hidden=\"true\">\n    <path fill=\"#FFC107\" d=\"M43.611 20.083H42V20H24v8h11.303c-1.649 4.657-6.08 8-11.303 8-6.627 0-12-5.373-12-12s5.373-12 12-12c3.059 0 5.842 1.154 7.961 3.039l5.657-5.657C34.046 6.053 29.268 4 24 4 12.955 4 4 12.955 4 24s8.955 20 20 20 20-8.955 20-20c0-1.341-.138-2.65-.389-3.917z\"/>\n    <path fill=\"#FF3D00\" d=\"M6.306 14.691l6.571 4.819C14.655 15.108 18.961 12 24 12c3.059 0 5.842 1.154 7.961 3.039l5.657-5.657C34.046 6.053 29.268 4 24 4 16.318 4 9.656 8.337 6.306 14.691z\"/>\n    <path fill=\"#4CAF50\" d=\"M24 44c5.166 0 9.86-1.977 13.409-5.192l-6.19-5.238C29.211 35.091 26.715 36 24 36c-5.202 0-9.619-3.317-11.283-7.946l-6.522 5.025C9.505 39.556 16.227 44 24 44z\"/>\n    <path fill=\"#1976D2\" d=\"M43.611 20.083H42V20H24v8h11.303a12.04 12.04 0 0 1-4.087 5.571l.003-.002 6.19 5.238C36.971 39.205 44 34 44 24c0-1.341-.138-2.65-.389-3.917z\"/>\n  </svg>\n);\n\nconst FacebookIcon = () => (\n  <svg className=\"w-5 h-5\" viewBox=\"0 0 24 24\" aria-hidden=\"true\">\n    <path fill=\"#1877F2\" d=\"M24 12.073c0-6.627-5.373-12-12-12s-12 5.373-12 12c0 5.99 4.388 10.954 10.125 11.854v-8.385H7.078v-3.47h3.047V9.43c0-3.007 1.792-4.669 4.533-4.669 1.312 0 2.686.235 2.686.235v2.953H15.83c-1.491 0-1.956.925-1.956 1.874v2.25h3.328l-.532 3.47h-2.796v8.385C19.612 23.027 24 18.062 24 12.073z\"/>\n  </svg>\n);\n\nexport function AuthModal({ isOpen, onClose, language, onAuthSuccess }: AuthModalProps) {\n  const [error, setError] = useState(\"\");\n  const [loading, setLoading] = useState(false);\n\n  const [step, setStep] = useState<\"start\" | \"phone\" | \"profile\">(\"start\");\n  const [googleUser, setGoogleUser] = useState<FirebaseUser | null>(null);\n  const [otpPhone, setOtpPhone] = useState(\"\");\n  // phoneAuthMode: OTP/SMS gateway সরিয়ে ফোন নম্বর + পাসওয়ার্ড দিয়ে লগইন/সাইনআপ করা হয়,\n  // কারণ SMS gateway (Android ফোন-ভিত্তিক) মাঝেমধ্যে অফলাইন/ব্যর্থ হয়ে যায়।\n  const [phoneAuthMode, setPhoneAuthMode] = useState<\"login\" | \"signup\">(\"login\");\n  const [phonePassword, setPhonePassword] = useState(\"\");\n  const [phonePasswordConfirm, setPhonePasswordConfirm] = useState(\"\");\n  const [displayName, setDisplayName] = useState(\"\");\n  const [phoneNumber, setPhoneNumber] = useState(\"\");\n  const [city, setCity] = useState(CITIES[0]);\n  const [profilePhotoFile, setProfilePhotoFile] = useState<File | null>(null);\n  const [profilePhotoPreview, setProfilePhotoPreview] = useState<string | null>(null);\n  const [uploadingPhoto, setUploadingPhoto] = useState(false);\n  const fileInputRef = useRef<HTMLInputElement>(null);\n\n  const handlePostGoogleAuth = async (fbUser: FirebaseUser) => {\n    const userDocRef = doc(db, \"users\", fbUser.uid);\n    const userSnap = await getDoc(userDocRef);\n\n    if (userSnap.exists()) {\n      const existingData = userSnap.data() as any;\n      const sessionUser = {\n        uid: fbUser.uid,\n        displayName: existingData.displayName,\n        email: existingData.email || fbUser.email,\n        phoneNumber: existingData.phoneNumber,\n        city: existingData.city,\n        profilePicture: existingData.profilePicture || fbUser.photoURL || PRESET_AVATARS[0],\n        simulatedCredits: existingData.simulatedCredits ?? 5000,\n        referralCode: existingData.referralCode,\n      };\n      localStorage.setItem(\"gari_bazar_session_user\", JSON.stringify(sessionUser));\n      trackEvent(\"login\", fbUser.uid, sessionUser.email || sessionUser.phoneNumber);\n      onAuthSuccess(sessionUser);\n      onClose();\n      return;\n    }\n\n    setGoogleUser(fbUser);\n    setDisplayName(fbUser.displayName || \"\");\n    setProfilePhotoPreview(fbUser.photoURL || null);\n    setStep(\"profile\");\n  };\n\n  React.useEffect(() => {\n    (async () => {\n      try {\n        const result = await getRedirectResult(auth);\n        if (result?.user) {\n          await handlePostGoogleAuth(result.user);\n        }\n      } catch (err) {\n        console.error(\"Redirect sign-in failed:\", err);\n      }\n    })();\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, []);\n\n  React.useEffect(() => {\n    if (!isOpen) {\n      setStep(\"start\");\n      setError(\"\");\n      setPhoneAuthMode(\"login\");\n      setPhonePassword(\"\");\n      setPhonePasswordConfirm(\"\");\n    }\n  }, [isOpen]);\n\n  if (!isOpen) return null;\n\n  const handlePhotoSelect = (e: React.ChangeEvent<HTMLInputElement>) => {\n    const file = e.target.files?.[0];\n    if (!file) return;\n\n    if (!file.type.startsWith(\"image/\")) {\n      setError(language === \"bn\" ? \"শুধু ছবি ফাইল দিতে পারবেন\" : \"Only image files are allowed\");\n      return;\n    }\n    if (file.size > 5 * 1024 * 1024) {\n      setError(language === \"bn\" ? \"ছবির সাইজ ৫MB এর কম হতে হবে\" : \"Photo must be under 5MB\");\n      return;\n    }\n\n    setError(\"\");\n    setProfilePhotoFile(file);\n    if (profilePhotoPreview) URL.revokeObjectURL(profilePhotoPreview);\n    setProfilePhotoPreview(URL.createObjectURL(file));\n  };\n\n  const handleGoogleSignIn = async () => {\n    setError(\"\");\n    setLoading(true);\n    try {\n      // Popup first on every device. signInWithRedirect depends on Firebase's\n      // authDomain (garibazar-bd.firebaseapp.com) sharing storage/cookies with\n      // this app's real hosting domain to hand back the result — Chrome's\n      // third-party storage partitioning breaks that bridge, which is why\n      // redirect sign-in was silently failing to persist. Popup avoids that\n      // entirely since it completes and resolves in the same tab session.\n      const result = await signInWithPopup(auth, googleProvider);\n      await handlePostGoogleAuth(result.user);\n    } catch (err: any) {\n      const code = err?.code || \"\";\n      if (code === \"auth/popup-closed-by-user\" || code === \"auth/cancelled-popup-request\") {\n        // ইউজার নিজেই popup বন্ধ করেছে\n      } else if (\n        code === \"auth/popup-blocked\" ||\n        code === \"auth/operation-not-supported-in-this-environment\"\n      ) {\n        try {\n          await signInWithRedirect(auth, googleProvider);\n          return;\n        } catch (redirectErr) {\n          console.error(redirectErr);\n          setError(language === \"bn\" ? \"Google সাইন-ইন করা যায়নি।\" : \"Could not sign in with Google.\");\n        }\n      } else {\n        console.error(err);\n        setError(language === \"bn\" ? \"Google সাইন-ইন ব্যর্থ হয়েছে। আবার চেষ্টা করুন।\" : \"Google sign-in failed. Please try again.\");\n      }\n    } finally {\n      setLoading(false);\n    }\n  };\n\n  const handleFacebookSignIn = async () => {\n    setError(\"\");\n    setLoading(true);\n    try {\n      const result = await signInWithPopup(auth, facebookProvider);\n      await handlePostGoogleAuth(result.user);\n    } catch (err: any) {\n      const code = err?.code || \"\";\n      if (code === \"auth/popup-closed-by-user\" || code === \"auth/cancelled-popup-request\") {\n        // ইউজার নিজেই popup বন্ধ করেছে\n      } else if (code === \"auth/account-exists-with-different-credential\") {\n        setError(\n          language === \"bn\"\n            ? \"এই ইমেইল দিয়ে আগে অন্য পদ্ধতিতে (যেমন Google) অ্যাকাউন্ট খোলা আছে। সেটা দিয়ে সাইন-ইন করুন।\"\n            : \"An account already exists with this email using a different sign-in method. Please use that instead.\"\n        );\n      } else if (\n        code === \"auth/popup-blocked\" ||\n        code === \"auth/operation-not-supported-in-this-environment\"\n      ) {\n        try {\n          await signInWithRedirect(auth, facebookProvider);\n          return;\n        } catch (redirectErr) {\n          console.error(redirectErr);\n          setError(language === \"bn\" ? \"Facebook সাইন-ইন করা যায়নি।\" : \"Could not sign in with Facebook.\");\n        }\n      } else {\n        console.error(err);\n        setError(language === \"bn\" ? \"Facebook সাইন-ইন ব্যর্থ হয়েছে। আবার চেষ্টা করুন।\" : \"Facebook sign-in failed. Please try again.\");\n      }\n    } finally {\n      setLoading(false);\n    }\n  };\n\n  const handlePhoneLogin = async (e: React.FormEvent) => {\n    e.preventDefault();\n    setError(\"\");\n    const cleanPhone = otpPhone.replace(/\\D/g, \"\");\n    if (!validateBanglaPhone(cleanPhone)) {\n      setError(language === \"bn\" ? \"সঠিক ১১ ডিজিটের মোবাইল নম্বর দিন\" : \"Enter a valid 11-digit phone number\");\n      return;\n    }\n    if (!phonePassword) {\n      setError(language === \"bn\" ? \"পাসওয়ার্ড দিন\" : \"Enter your password\");\n      return;\n    }\n    setLoading(true);\n    try {\n      const resp = await fetch(\"/api/auth/phone-login\", {\n        method: \"POST\",\n        headers: { \"Content-Type\": \"application/json\" },\n        body: JSON.stringify({ phone: cleanPhone, password: phonePassword }),\n      });\n      const data = await resp.json();\n      if (!resp.ok) {\n        if (data.code === \"NOT_REGISTERED\") {\n          setPhoneAuthMode(\"signup\");\n        }\n        setError(data.error || (language === \"bn\" ? \"লগইন ব্যর্থ হয়েছে।\" : \"Login failed.\"));\n        return;\n      }\n      const result = await signInWithCustomToken(auth, data.token);\n      await handlePostGoogleAuth(result.user);\n    } catch (err: any) {\n      console.error(err);\n      setError(language === \"bn\" ? \"সাইন-ইন ব্যর্থ হয়েছে। আবার চেষ্টা করুন।\" : \"Sign-in failed. Please try again.\");\n    } finally {\n      setLoading(false);\n    }\n  };\n\n  const handlePhoneSignup = async (e: React.FormEvent) => {\n    e.preventDefault();\n    setError(\"\");\n    const cleanPhone = otpPhone.replace(/\\D/g, \"\");\n    if (!validateBanglaPhone(cleanPhone)) {\n      setError(language === \"bn\" ? \"সঠিক ১১ ডিজিটের মোবাইল নম্বর দিন\" : \"Enter a valid 11-digit phone number\");\n      return;\n    }\n    if (phonePassword.length < 6) {\n      setError(language === \"bn\" ? \"পাসওয়ার্ড কমপক্ষে ৬ ক্যারেক্টার হতে হবে\" : \"Password must be at least 6 characters\");\n      return;\n    }\n    if (phonePassword !== phonePasswordConfirm) {\n      setError(language === \"bn\" ? \"দুই পাসওয়ার্ড মিলছে না\" : \"Passwords don't match\");\n      return;\n    }\n    setLoading(true);\n    try {\n      const resp = await fetch(\"/api/auth/phone-signup\", {\n        method: \"POST\",\n        headers: { \"Content-Type\": \"application/json\" },\n        body: JSON.stringify({ phone: cleanPhone, password: phonePassword }),\n      });\n      const data = await resp.json();\n      if (!resp.ok) {\n        if (data.code === \"ALREADY_REGISTERED\") {\n          setPhoneAuthMode(\"login\");\n        }\n        setError(data.error || (language === \"bn\" ? \"অ্যাকাউন্ট তৈরি করা যায়নি।\" : \"Could not create account.\"));\n        return;\n      }\n      const result = await signInWithCustomToken(auth, data.token);\n      await handlePostGoogleAuth(result.user);\n    } catch (err: any) {\n      console.error(err);\n      setError(language === \"bn\" ? \"সাইন-ইন ব্যর্থ হয়েছে। আবার চেষ্টা করুন।\" : \"Sign-in failed. Please try again.\");\n    } finally {\n      setLoading(false);\n    }\n  };\n\n  const handleCancelProfileStep = async () => {\n    try { await signOut(auth); } catch { /* ignore */ }\n    setGoogleUser(null);\n    setStep(\"start\");\n    setError(\"\");\n  };\n\n  const handleCompleteProfile = async (e: React.FormEvent) => {\n    e.preventDefault();\n    setError(\"\");\n    if (!googleUser) return;\n\n    const cleanPhone = phoneNumber.replace(/\\D/g, \"\");\n    if (!validateBanglaPhone(cleanPhone)) {\n      setError(language === \"bn\" ? \"সঠিক ১১ ডিজিটের মোবাইল নম্বর দিন\" : \"Enter a valid 11-digit phone number\");\n      return;\n    }\n\n    setLoading(true);\n    try {\n      const sanitizedDisplayName = sanitizeText(displayName || googleUser.displayName || \"Gari Bazar Seller\", 50);\n      const myReferralCode = `GB-${cleanPhone.slice(-4)}`;\n\n      let uploadedPhotoUrl = googleUser.photoURL || PRESET_AVATARS[0];\n      if (profilePhotoFile) {\n        setUploadingPhoto(true);\n        try {\n          const compressedBlob = await compressImageToBlob(profilePhotoFile);\n          const uploadPromise = uploadToCloudinary(compressedBlob);\n          const timeoutPromise = new Promise<never>((_, reject) =>\n            setTimeout(() => reject(new Error(\"upload/timeout\")), 60000)\n          );\n          uploadedPhotoUrl = await Promise.race([uploadPromise, timeoutPromise]);\n        } catch (photoErr: any) {\n          console.error(\"Profile photo upload failed:\", photoErr);\n          setUploadingPhoto(false);\n          setLoading(false);\n          setError(\n            photoErr?.message === \"upload/timeout\"\n              ? (language === \"bn\" ? \"ছবি আপলোড আটকে গেছে (Timeout)! আবার চেষ্টা করুন।\" : \"Photo upload timed out. Please try again.\")\n              : (language === \"bn\" ? \"ছবি আপলোড ব্যর্থ হয়েছে। আবার চেষ্টা করুন অথবা ছবি ছাড়াই এগিয়ে যান।\" : \"Photo upload failed. Try again or continue without a photo.\")\n          );\n          return;\n        }\n        setUploadingPhoto(false);\n      }\n\n      const savedData = {\n        uid: googleUser.uid,\n        displayName: sanitizedDisplayName,\n        email: googleUser.email,\n        phoneNumber: cleanPhone,\n        city: sanitizeText(city, 50),\n        profilePicture: uploadedPhotoUrl,\n        createdAt: new Date().toISOString(),\n        simulatedCredits: 5000,\n        referralCode: myReferralCode,\n      };\n\n      await setDoc(doc(db, \"users\", googleUser.uid), savedData);\n      localStorage.setItem(\"gari_bazar_session_user\", JSON.stringify(savedData));\n      trackEvent(\"signup\", googleUser.uid, savedData.email || savedData.phoneNumber);\n      onAuthSuccess(savedData);\n      onClose();\n    } catch (err) {\n      console.error(err);\n      setError(language === \"bn\" ? \"কিছু একটা সমস্যা হয়েছে।\" : \"Something went wrong.\");\n    } finally {\n      setLoading(false);\n    }\n  };\n\n  return (\n    <div className=\"fixed inset-0 bg-slate-900/60 backdrop-blur-xs flex items-center justify-center p-4 z-50\">\n      <div className=\"bg-white dark:bg-slate-900 rounded-2xl max-w-md w-full shadow-2xl p-6 relative\">\n        <button onClick={onClose} className=\"absolute top-4 right-4 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200\">\n          <X className=\"w-5 h-5\" />\n        </button>\n\n        <div className=\"text-center mb-6\">\n          <h2 className=\"text-xl font-black text-slate-900 dark:text-white\">\n            {step === \"profile\"\n              ? (language === \"bn\" ? \"প্রোফাইল সম্পূর্ণ করুন\" : \"Complete Your Profile\")\n              : (language === \"bn\" ? \"স্বাগতম\" : \"Welcome\")}\n          </h2>\n        </div>\n\n        {error && <div className=\"p-3 bg-red-500/10 text-red-600 rounded-lg text-xs mb-3 text-center\">{error}</div>}\n\n        {step === \"start\" ? (\n          <div className=\"space-y-4\">\n            <p className=\"text-sm text-slate-500 dark:text-slate-400 text-center\">\n              {language === \"bn\"\n                ? \"গাড়ি বাজারে বিক্রি করতে বা কেনার জন্য সাইন-ইন করুন।\"\n                : \"Sign in to buy or sell on Gari Bazar.\"}\n            </p>\n            <button\n              type=\"button\"\n              onClick={handleGoogleSignIn}\n              disabled={loading}\n              className=\"w-full py-2.5 bg-white hover:bg-slate-50 disabled:opacity-60 text-slate-700 font-bold rounded-lg text-sm flex items-center justify-center gap-2 border border-slate-300 dark:border-slate-600 dark:bg-slate-800 dark:text-white dark:hover:bg-slate-700\"\n            >\n              {loading ? <Loader2 className=\"w-4 h-4 animate-spin\" /> : <GoogleIcon />}\n              {language === \"bn\" ? \"Google দিয়ে চালিয়ে যান\" : \"Continue with Google\"}\n            </button>\n            <button\n              type=\"button\"\n              onClick={() => { setError(\"\"); setStep(\"phone\"); }}\n              disabled={loading}\n              className=\"w-full py-2.5 bg-emerald-600 hover:bg-emerald-700 disabled:opacity-60 text-white font-bold rounded-lg text-sm flex items-center justify-center gap-2\"\n            >\n              <Phone className=\"w-4 h-4\" />\n              {language === \"bn\" ? \"মোবাইল নম্বর দিয়ে চালিয়ে যান\" : \"Continue with Phone\"}\n            </button>\n          </div>\n        ) : step === \"phone\" ? (\n          <form onSubmit={phoneAuthMode === \"login\" ? handlePhoneLogin : handlePhoneSignup} className=\"space-y-4\">\n            <p className=\"text-xs text-slate-500 text-center\">\n              {phoneAuthMode === \"login\"\n                ? (language === \"bn\" ? \"আপনার মোবাইল নম্বর ও পাসওয়ার্ড দিয়ে সাইন-ইন করুন।\" : \"Sign in with your mobile number and password.\")\n                : (language === \"bn\" ? \"নতুন অ্যাকাউন্ট তৈরি করতে মোবাইল নম্বর ও পাসওয়ার্ড দিন।\" : \"Enter a mobile number and password to create your account.\")}\n            </p>\n            <div>\n              <label className=\"text-[10px] font-bold block mb-1 text-slate-500\">{language === \"bn\" ? \"মোবাইল নম্বর *\" : \"Mobile Number *\"}</label>\n              <input\n                type=\"tel\"\n                required\n                autoFocus\n                value={otpPhone}\n                onChange={(e) => setOtpPhone(e.target.value)}\n                className=\"w-full px-3 py-2 text-sm border rounded-lg dark:bg-slate-800 dark:border-slate-700 dark:text-white\"\n                placeholder=\"01XXXXXXXXX\"\n              />\n            </div>\n            <div>\n              <label className=\"text-[10px] font-bold block mb-1 text-slate-500\">{language === \"bn\" ? \"পাসওয়ার্ড *\" : \"Password *\"}</label>\n              <input\n                type=\"password\"\n                required\n                value={phonePassword}\n                onChange={(e) => setPhonePassword(e.target.value)}\n                className=\"w-full px-3 py-2 text-sm border rounded-lg dark:bg-slate-800 dark:border-slate-700 dark:text-white\"\n                placeholder={language === \"bn\" ? \"কমপক্ষে ৬ ক্যারেক্টার\" : \"At least 6 characters\"}\n              />\n            </div>\n            {phoneAuthMode === \"signup\" && (\n              <div>\n                <label className=\"text-[10px] font-bold block mb-1 text-slate-500\">{language === \"bn\" ? \"পাসওয়ার্ড আবার দিন *\" : \"Confirm Password *\"}</label>\n                <input\n                  type=\"password\"\n                  required\n                  value={phonePasswordConfirm}\n                  onChange={(e) => setPhonePasswordConfirm(e.target.value)}\n                  className=\"w-full px-3 py-2 text-sm border rounded-lg dark:bg-slate-800 dark:border-slate-700 dark:text-white\"\n                  placeholder={language === \"bn\" ? \"পাসওয়ার্ড আবার লিখুন\" : \"Re-enter password\"}\n                />\n              </div>\n            )}\n            <button type=\"submit\" disabled={loading} className=\"w-full py-2.5 bg-emerald-600 hover:bg-emerald-700 disabled:opacity-60 text-white font-bold rounded-lg text-sm flex items-center justify-center gap-2\">\n              {loading ? <Loader2 className=\"w-4 h-4 animate-spin\" /> : <Phone className=\"w-4 h-4\" />}\n              {phoneAuthMode === \"login\"\n                ? (language === \"bn\" ? \"সাইন-ইন করুন\" : \"Sign In\")\n                : (language === \"bn\" ? \"অ্যাকাউন্ট তৈরি করুন\" : \"Create Account\")}\n            </button>\n            <div className=\"flex items-center justify-between text-xs\">\n              <button type=\"button\" onClick={() => { setError(\"\"); setStep(\"start\"); }} className=\"flex items-center gap-1 text-slate-500 hover:underline\">\n                <ArrowLeft className=\"w-3 h-3\" />\n                {language === \"bn\" ? \"পেছনে যান\" : \"Back\"}\n              </button>\n              <button\n                type=\"button\"\n                onClick={() => { setError(\"\"); setPhoneAuthMode(phoneAuthMode === \"login\" ? \"signup\" : \"login\"); }}\n                className=\"text-emerald-600 font-bold hover:underline\"\n              >\n                {phoneAuthMode === \"login\"\n                  ? (language === \"bn\" ? \"নতুন অ্যাকাউন্ট তৈরি করুন\" : \"Create new account\")\n                  : (language === \"bn\" ? \"আগে থেকে অ্যাকাউন্ট আছে? সাইন-ইন\" : \"Already have an account? Sign in\")}\n              </button>\n            </div>\n          </form>\n        ) : (\n          <form onSubmit={handleCompleteProfile} className=\"space-y-4\">\n            <p className=\"text-xs text-slate-500 text-center\">\n              {language === \"bn\"\n                ? \"শেষ ধাপ! ক্রেতারা যেন আপনার সাথে যোগাযোগ করতে পারে, তাই একটা মোবাইল নম্বর ও জেলা দিন।\"\n                : \"Almost done! Add a phone number and district so buyers can contact you.\"}\n            </p>\n\n            <div className=\"flex justify-center mb-2\">\n              <button\n                type=\"button\"\n                onClick={() => fileInputRef.current?.click()}\n                className=\"relative w-20 h-20 rounded-full overflow-hidden border-2 border-dashed border-slate-300 dark:border-slate-600 flex items-center justify-center bg-slate-50 dark:bg-slate-800\"\n              >\n                {profilePhotoPreview ? (\n                  <>\n                    <img src={profilePhotoPreview} alt=\"preview\" className=\"w-full h-full object-cover\" />\n                    <span className=\"absolute bottom-0 inset-x-0 bg-slate-900/60 text-white flex items-center justify-center py-1\">\n                      <Camera className=\"w-3.5 h-3.5\" />\n                    </span>\n                  </>\n                ) : (\n                  <>\n                    <Camera className=\"w-6 h-6 text-slate-400\" />\n                    <div className=\"absolute bottom-0 inset-x-0 bg-black/50 text-white text-[9px] font-bold text-center py-0.5\">\n                      {language === \"bn\" ? \"ছবি দিন\" : \"Add Photo\"}\n                    </div>\n                  </>\n                )}\n              </button>\n              <input type=\"file\" ref={fileInputRef} onChange={handlePhotoSelect} accept=\"image/*\" className=\"hidden\" />\n            </div>\n\n            <div>\n              <label className=\"text-[10px] font-bold block mb-1 text-slate-500\">{language === \"bn\" ? \"আপনার নাম *\" : \"Name *\"}</label>\n              <div className=\"relative\">\n                <input type=\"text\" required value={displayName} onChange={(e) => setDisplayName(e.target.value)} className=\"w-full px-3 py-2 text-sm border rounded-lg dark:bg-slate-800 dark:border-slate-700 dark:text-white\" placeholder=\"Rayhan\" />\n              </div>\n            </div>\n\n            <div>\n              <label className=\"text-[10px] font-bold block mb-1 text-slate-500\">{language === \"bn\" ? \"মোবাইল নম্বর *\" : \"Mobile Number *\"}</label>\n              <div className=\"relative\">\n                <input type=\"tel\" required value={phoneNumber} onChange={(e) => setPhoneNumber(e.target.value)} className=\"w-full px-3 py-2 text-sm border rounded-lg dark:bg-slate-800 dark:border-slate-700 dark:text-white\" placeholder=\"01993878271\" />\n              </div>\n              <p className=\"text-[10px] text-slate-400 mt-1\">\n                {language === \"bn\" ? \"এই নম্বরে OTP পাঠানো হবে না — শুধু যোগাযোগের জন্য দেখানো হবে।\" : \"No OTP is sent here — it's shown to buyers as your contact number.\"}\n              </p>\n            </div>\n\n            <div>\n              <label className=\"text-[10px] font-bold block mb-1 text-slate-500\">{language === \"bn\" ? \"জেলা *\" : \"District *\"}</label>\n              <div className=\"relative\">\n                <MapPin className=\"w-4 h-4 text-slate-400 absolute left-3 top-3\" />\n                <select value={city} onChange={(e) => setCity(e.target.value)} className=\"w-full pl-9 pr-3 py-2 text-sm border rounded-lg dark:bg-slate-800 dark:border-slate-700 dark:text-white appearance-none\">\n                  {CITIES.map((c) => <option key={c} value={c}>{c}</option>)}\n                </select>\n              </div>\n            </div>\n\n            <button type=\"submit\" disabled={loading} className=\"w-full py-2.5 bg-amber-500 hover:bg-amber-600 disabled:bg-amber-300 text-white font-bold rounded-lg text-sm flex items-center justify-center gap-2\">\n              {loading ? <Loader2 className=\"w-4 h-4 animate-spin\" /> : <Sparkles className=\"w-4 h-4\" />}\n              {uploadingPhoto\n                ? (language === \"bn\" ? \"ছবি আপলোড হচ্ছে...\" : \"Uploading photo...\")\n                : (language === \"bn\" ? \"প্রোফাইল তৈরি করুন\" : \"Create Profile\")}\n            </button>\n\n            <button type=\"button\" onClick={handleCancelProfileStep} className=\"w-full text-center text-xs text-slate-500 hover:underline\">\n              {language === \"bn\" ? \"← বাতিল করুন\" : \"← Cancel\"}\n            </button>\n          </form>\n        )}\n      </div>\n    </div>\n  );\n      }\n"


def write_if_needed(path, content, label):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    if os.path.exists(path):
        with open(path, "r", encoding="utf-8") as f:
            existing = f.read()
        if existing.strip() == content.strip():
            print(f"SKIP: {label} ইতিমধ্যে আপ টু ডেট")
            return
    with open(path, "w", encoding="utf-8") as f:
        f.write(content)
    print(f"OK: {label} লেখা হয়েছে")


def patch_server():
    if not os.path.exists(SERVER_PATH):
        print("ERROR: server.ts পাওয়া যায়নি")
        sys.exit(1)
    with open(SERVER_PATH, "r", encoding="utf-8") as f:
        content = f.read()

    if "phoneLoginHandler" in content:
        print("SKIP: server.ts ইতিমধ্যে patched")
        return

    if SERVER_IMPORT_OLD not in content or SERVER_ROUTE_OLD not in content:
        print("ERROR: server.ts-এর প্রত্যাশিত অংশ খুঁজে পাওয়া যায়নি, ম্যানুয়ালি চেক করো")
        sys.exit(1)

    content = content.replace(SERVER_IMPORT_OLD, SERVER_IMPORT_NEW, 1)
    content = content.replace(SERVER_ROUTE_OLD, SERVER_ROUTE_NEW, 1)
    with open(SERVER_PATH, "w", encoding="utf-8") as f:
        f.write(content)
    print("OK: server.ts patched")


def patch_authmodal():
    if not os.path.exists(AUTHMODAL_PATH):
        print("ERROR: AuthModal.tsx পাওয়া যায়নি")
        sys.exit(1)
    with open(AUTHMODAL_PATH, "r", encoding="utf-8") as f:
        content = f.read()

    if "handlePhoneLogin" in content:
        print("SKIP: AuthModal.tsx ইতিমধ্যে patched")
        return

    if content.strip() != AUTHMODAL_OLD.strip():
        print("ERROR: AuthModal.tsx আশানুরূপ অবস্থায় নেই (হয়তো আগে থেকেই এডিট করা আছে)।")
        print("       ম্যানুয়ালি চেক করো, বা আমাকে জানাও।")
        sys.exit(1)

    with open(AUTHMODAL_PATH, "w", encoding="utf-8") as f:
        f.write(AUTHMODAL_NEW)
    print("OK: src/components/AuthModal.tsx patched")


if __name__ == "__main__":
    write_if_needed(PHONE_SIGNUP_PATH, PHONE_SIGNUP_CONTENT, "api/auth/phone-signup.ts")
    write_if_needed(PHONE_LOGIN_PATH, PHONE_LOGIN_CONTENT, "api/auth/phone-login.ts")
    patch_server()
    patch_authmodal()
    print("\nসম্পন্ন! এখন:")
    print("  git add api/auth/phone-signup.ts api/auth/phone-login.ts server.ts src/components/AuthModal.tsx")
    print('  git commit -m "feat: phone+password login/signup, remove SMS-gateway OTP dependency"')
    print("  git push")
